lines=['# Geometry allocation before door revision','2026-11-19. Written before further modelling. R2 is preserved; no limits changed.','','## Decoded R2 GLB: exact delivery counts','| Mesh component | Triangles |','|---|---:|']+[f"| {n['node']} | {n['triangles']:,} |" for n in nodes]
